function validate([image, x, y]) {
  const m = image.length;
  if (m < 1 || m > 100) return 'image needs 1 to 100 rows.';
  const n = image[0].length;
  if (n < 1 || n > 100) return 'image needs 1 to 100 columns.';
  if (image.some(row => row.length !== n)) return 'Every row must have the same length.';
  if (image.some(row => row.some(cell => cell !== '0' && cell !== '1'))) return "Each pixel is '0' or '1'.";
  if (!Number.isInteger(x) || !Number.isInteger(y) || x < 0 || x >= m || y < 0 || y >= n) return 'x and y must point inside the image.';
  if (image[x][y] !== '1') return 'The pixel at (x, y) must be black.';
  let total = 0;
  for (const row of image) for (const cell of row) if (cell === '1') total++;
  const seen = image.map(row => row.map(() => false));
  const stack = [[x, y]];
  seen[x][y] = true;
  let reached = 0;
  while (stack.length) {
    const [r, c] = stack.pop();
    reached++;
    for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
      if (nr >= 0 && nr < m && nc >= 0 && nc < n && !seen[nr][nc] && image[nr][nc] === '1') {
        seen[nr][nc] = true;
        stack.push([nr, nc]);
      }
    }
  }
  if (reached !== total) return 'The black pixels must form one connected group.';
  return null;
}

