function minArea(image, x, y) {
  const rows = image.length;
  const cols = image[0].length;
  const rowHasBlack = (row) => image[row].includes('1');
  const colHasBlack = (col) => image.some((line) => line[col] === '1');

  // Smallest index in [low, high) where hasBlack(index) equals wanted, or high if there is none.
  const firstWhere = (low, high, hasBlack, wanted) => {
    while (low < high) {
      const mid = Math.floor((low + high) / 2);
      if (hasBlack(mid) === wanted) {
        high = mid;
      } else {
        low = mid + 1;
      }
    }
    return low;
  };

  const top = firstWhere(0, x, rowHasBlack, true);
  const bottom = firstWhere(x + 1, rows, rowHasBlack, false);
  const left = firstWhere(0, y, colHasBlack, true);
  const right = firstWhere(y + 1, cols, colHasBlack, false);
  return (bottom - top) * (right - left);
}

