function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const m = size === 'large' ? 60 + pick(41) : 1 + pick(6);
  const n = size === 'large' ? 60 + pick(41) : 1 + pick(6);
  const image = Array.from({ length: m }, () => new Array(n).fill('0'));
  const cells = [];
  const add = (r, c) => {
    if (image[r][c] === '1') return;
    image[r][c] = '1';
    cells.push([r, c]);
  };
  const steps = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const inside = (r, c) => r >= 0 && r < m && c >= 0 && c < n;
  const target = 1 + pick(Math.max(1, Math.floor(m * n * (size === 'large' ? 0.3 : 0.7))));
  add(pick(m), pick(n));
  if (rand() < 0.5) {
    // A random walk gives thin, winding shapes that stretch across the grid.
    let [r, c] = cells[0];
    for (let step = 0; step < target * 4 && cells.length < target; step++) {
      const [dr, dc] = steps[pick(4)];
      if (!inside(r + dr, c + dc)) continue;
      r += dr;
      c += dc;
      add(r, c);
    }
  } else {
    // Growing from random black pixels gives blobby shapes.
    for (let tries = 0; tries < target * 8 && cells.length < target; tries++) {
      const [r, c] = cells[pick(cells.length)];
      const [dr, dc] = steps[pick(4)];
      if (inside(r + dr, c + dc)) add(r + dr, c + dc);
    }
  }
  const [x, y] = cells[pick(cells.length)];
  return [image, x, y];
}
